def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

pairs = []
# q must be an odd prime, q < 400 (since q+r=800 and q < r)
for q in range(3, 400):
    if is_prime(q):
        r = 800 - q
        if r > q and is_prime(r):
            pairs.append((q, r))

print("Prime pairs (q, r) summing to 800:")
for pair in pairs:
    print(pair)

# Now iterate through the pairs and check for suitable p
results = []
for q, r in pairs:
    print(f"\n--- Checking pairs where (q, r) = ({q}, {r}) ---")
    potential_p = []
    # p must be prime and p < q
    for p in range(2, q):
        if is_prime(p):
            # Constraint 1: p+q+r = p+800 must be prime
            if not is_prime(p + 800):
                continue

            # Constraint 2: q+r-p = 800-p must be prime
            if not is_prime(800 - p):
                continue

            # Constraint 3: p+q-r = p + 2q - 800 must be prime
            c3 = p + 2 * q - 800
            if not is_prime(c3):
                continue

            # Constraint 4: r+p-q = 800 + p - 2q must be prime
            c4 = 800 + p - 2 * q
            if not is_prime(c4):
                continue

            # All constraints met
            potential_p.append(p)

    if potential_p:
        results.append({
            'q': q,
            'r': r,
            'p_values': potential_p
        })

print("\n--- Final Results ---")
if results:
    for res in results:
        print(f"Found solution family: q={res['q']}, r={res['r']}. Possible p values: {res['p_values']}")
else:
    print("No solutions found for q+r=800.")

